scan_table_check.script:
(function(engine, current) {
    var context = new global.EcsContext(current);
    if (context.value('collection') !== 'global') {
        return;
    }
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-BR-004',
        title: 'Global Business Rule',
        recommendation: 'Move shared functions to a Script Include, which is loaded only when it is used. If the ' +
            'logic must react to records, put the Business Rule on the specific table it concerns.',
        current: current
    });
    report.addRecord('Business Rule "' + context.value('name') + '" is defined on the Global table, so the platform ' +
        'loads it for every server-side transaction instead of only where it is needed.');
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
